@pytest.fixture
def status_org_stats_data(db):
    orgs = [OrganizationFactory(title=name) for name in ORG_NAMES]
    ds = []
    org_assignments = [orgs[0], orgs[0], orgs[1], orgs[2]]
    for i, org in enumerate(org_assignments):
        d = DatasetFactory(organization=org)
        DatasetStatsFactory(
            dataset_id=d.pk,
            created=date(2022, 12, 28),
            object_count=10 + i,
            maturity_level=(i % 5) + 1,
        )
        DatasetStatsFactory(
            dataset_id=d.pk,
            created=date(2023, 1, 3),
            object_count=20 + i,
            maturity_level=(i % 5) + 1,
        )
        ds.append(d)
    return ds


@pytest.mark.haystack
@pytest.mark.django_db
@pytest.mark.parametrize("duration", DURATIONS)
@pytest.mark.parametrize("indicator", INDICATORS)
def test_org_stats_snapshot(app: DjangoTestApp, status_org_stats_data, duration, indicator):
    with freeze_time(FROZEN_NOW):
        resp = app.get(
            reverse("dataset-stats-organization"),
            params={"indicator": indicator, "duration": duration},
        )
    assert resp.status_code == 200
    snapshot = {
        "time_chart_data": resp.context["time_chart_data"],
        "bar_chart_data": [
            {"display_value": str(b.get("display_value")), "count": b.get("count")}
            for b in resp.context["bar_chart_data"]
        ],
        "max_count": resp.context["max_count"],
    }
    assert len(snapshot["bar_chart_data"]) >= 2, (
        f"Expected multiple org buckets but got {len(snapshot['bar_chart_data'])}; "
        f"datasets not faceted by organization — check ES indexing"
    )
    assert normalize_chart_snapshot(snapshot) == normalize_chart_snapshot(EXPECTED[(indicator, duration)])


@pytest.mark.haystack
@pytest.mark.django_db
def test_org_stats_query_count(app: DjangoTestApp, status_org_stats_data):
    with freeze_time(FROZEN_NOW):
        with CaptureQueriesContext(connection) as ctx:
            app.get(
                reverse("dataset-stats-organization"),
                params={"indicator": "object-count", "duration": "duration-daily"},
            )

    data_queries = [q for q in ctx.captured_queries if "dataset_statistic" in q["sql"]]
    assert len(data_queries) <= 10, (
        f"Expected ≤10 dataset_statistic queries but got {len(data_queries)}. "
        f"The N+1 pattern may have been reintroduced (pre-refactor baseline was 96)."
    )
